        parse_session_log(["", "  # comment", "b,1,1", bad_line])


def test_dedupe_sessions_keeps_last_duplicate_and_sorts_by_day_then_id():
    earlier_a = {"id": "a", "day": 5, "converted": True}
    later_a = {"id": "a", "day": 2, "converted": False}
    b = {"id": "b", "day": 2, "converted": True}
    c = {"id": "c", "day": 1, "converted": None}
    assert dedupe_sessions([earlier_a, b, c, later_a]) == [c, later_a, b]


def test_daily_conversion_counts_includes_empty_days_and_ignores_outside_range():
